   "desc": "ಹಾಡೊಂದನ್ನು ಲೋಕ್ ಮಾಡಿ, ಸಾಹಿತ್ಯವನ್ನು ಅಂಟಿಸಿ, ನೀವು ಕೇಳಿಸಿಕೊಳ್ಳುತ್ತಾ ಪ್ರತಿ ಸಾಲಿಗೆ ಒಂದು ಟೈಮ್‌ಸ್ಟ್ಯಾಂಪ್ ಅನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿ, ಮತ್ತು LRC ಅಥವಾ SRT ಅನ್ನು ಎಪೋರ್ಟ್ ಮಾಡಿ. ಸ್ಪೇಸ್ ಪ್ಲೇ ಹಾಗೂ ಪಾಸ್ ಮಾಡುತ್ತದೆ, ಎಂಟರ್ ಸಾಲನ್ನು ಸ್ಟ್ಯಾಂಪ್ ಮಾಡುತ್ತದೆ, Z ರದ್ದುಗೊಳಿಸುತ್ತದೆ, ಕೈಗಳು ಕೀಬೋರ್ಡ್‌ ಮೇಲೆಯೇ ಇರುತ್ತವೆ.",
   "h1": "ಗೀತೆ ಸಿಂಕ್ ಉಪಕರಣವನ್ನು ಬಳಸುವುದು ಹೇಗೆ",
   "intro": "ಹಾಡೊಂದನ್ನು ಲೋಕ್ ಮಾಡಿ, ಸಾಹಿತ್ಯವನ್ನು ಅಂಟಿಸಿ, ನೀವು ಕೇಳಿಸಿಕೊಳ್ಳುತ್ತಾ ಪ್ರತಿ ಸಾಲಿಗೆ ಒಂದು ಟೈಮ್‌ಸ್ಟ್ಯಾಂಪ್ ಅನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿ, ಮತ್ತು ಪ್ರಮಾಣಿತ LRC ಅಥವಾ SRT ಅನ್ನು ಎಪೋರ್ಟ್ ಮಾಡಿ. ಆಡಿಯೋ ಸ್ಥಳೀಯವಾಗಿ ಪ್ಲೇ ಆಗುತ್ತದೆ ಮತ್ತು ಎಂದಿಗೂ ಅಪ್‌ಲೋಡ್ ಆಗುವುದಿಲ್ಲ.",
   "ctaText": "ಗೀತೆ ಸಿಂಕ್ ಉಪಕರಣವನ್ನು ತೆರೆಯಿರಿ"
