     "**ಎಕ್ಸ್‌ಪೋರ್ಟ್‌ನಿಂದ ಕೆಲವು ಸಾಲುಗಳು ಯಾಕೆ ಕಾಣೆಯಾಗಿವೆ?** ಬಿಟ್ಟುಬಿಟ್ಟ ಸಾಲುಗಳು ಮತ್ತು ಸಮಯವಿಲ್ಲದ ಸಾಲುಗಳು ಎಂದಿಗೂ ಕಡತಕ್ಕೆ ಪ್ರವೇಶಿಸುವುದಿಲ್ಲ. ಮೂರನೇ ಹಂತಕ್ಕೆ ಹಿಂತಿರುಗಿ ಅವುಗಳನ್ನು ಸೇರಿಸಿ, ಅಥವಾ ಅವುಗಳನ್ನು ಬಿಟ್ಟುಬಿಡಲು ಉದ್ದೇಶಿಸಲಾಗಿದೆ ಎಂದು ಖಚಿತಪಡಿಸಿ.",
