     "ಎರಡೂ ಕಡತಗಳು ಒಂದೇ ಕ್ರಮದಲ್ಲಿ ಒಂದೇ ಸಂಖ್ಯೆಯ ನಮೂದನೆಗಳನ್ನು ಹೊಂದಿರುವಾಗ, ಕ್ರಮದ ಮೂಲಕ ಜೋಡಿಸುವುದು ಸುರಕ್ಷಿತವಾಗಿದೆ. ಎಣಿಕೆಗಳು ಭಿನ್ನವಾಗಿರುವಾಗ (ಒಂದು მხರೆ ನಮೂದನೆಗಳನ್ನು ವಿಲೀನಗೊಳಿಸಿದೆ, ಇನ್ನೊಂದು ಕಡೆ ಅವುಗಳನ್ನು ವಿಭಜಿಸಿದೆ), ಟೈಮ್‌ಲೈನ್ ಮೂಲಕ ಜೋಡಿಸಿ ಮತ್ತು ಸಾಮೀಪ್ಯದ ಮೂಲಕ ಹೊಂದಿಸಲು ಉಪಕರಣಕ್ಕೆ ಅವಕಾಶ ಮಾಡಿಕೊಡಿ. ಯಾರ ಟೈಮ್‌ಲೈನ್ ಅನ್ನು ಬಳಸಬೇಕು ಎಂಬುದು ಯಾವ ಕಡತವು ಹೆಚ್ಚು ನಿಖರವಾಗಿದೆ ಎಂಬುದರ ಮೇಲೆ ಅವಲಂಬಿತವಾಗಿರುತ್ತದೆ — ಸಾಮಾನ್ಯವಾಗಿ ಮೂಲ ಕಡತ.",
