     "ನೀವು ದ್ವಿಭಾಷಾ VTT ಶೈಲಿಯನ್ನು ಎಕ್ಸ್‌ಪೋರ್ಟ್ ಮಾಡಿದಾಗ, \"WebVTT style\" ಬ್ಲಾಕ್ ಅನ್ವಯಿಸುತ್ತದೆ: ಆರು ಮುನ್ನೆಲೆ ಸೆಟ್‌ಗಳ (presets - standard / compact / cinematic / top / accessible / portrait) ಮೇಲ್ಭಾಗದಲ್ಲಿ ನೀವು ಲಂಬ ಸಾಲು, ಆಂಕರ್ (bottom / top / centre), ಸಮತಲ ಸ್ಥಾನ, ಅಗಲ ಗಾತ್ರ, ಜೋಡಣೆ ಮೌಲ್ಯ ಮತ್ತು ಸಂಪೂರ್ಣ ಕ್ಯೂನ ಸಾಲಿನ ಎತ್ತರವನ್ನು ಬದಲಾಯಿಸಬಹುದು, ಜೊತೆಗೆ ಅನುವಾದ ಸಾಲಿನ ಹಿನ್ನೆಲೆ ಬಣ್ಣ, ಹಿನ್ನೆಲೆ ಅಪಾರದರ್ಶಕತೆ ಮತ್ತು ಹೊರರೇಖೆಯ ಅಗಲವನ್ನು ಬದಲಾಯಿಸಬಹುದು; ಮೂಲ ಸಾಲು ಮುಖ್ಯ ಶೈಲಿಯನ್ನು ಆನುವಂಶಿಕವಾಗಿ ಪಡೆಯಬಹುದು ಅಥವಾ ಪ್ರತ್ಯೇಕವಾಗಿ ಹೊಂದಿಸಬಹುದು.",
