     "**ಎಕ್ಸ್‌ಪೋರ್ಟ್ ಮಾಡಿದ ASS ನಲ್ಲಿ ಪ್ಲೇಯರ್ ಶೈಲಿಯನ್ನು ನಿರ್ಲಕ್ಷಿಸಿದರೆ ಏನು ಮಾಡಬೇಕು?** ಶೈಲಿಗಳನ್ನು ಕಡತದೊಳಗೆ ಸಂಗ್ರಹಿಸಲಾಗುತ್ತದೆ, ಆದರೆ ASS ಗಾಗಿ ಪ್ಲೇಯರ್ ಬೆಂಬಲವು ಬದಲಾಗುತ್ತದೆ. ನಿಮಗೆ ಹೆಚ್ಚು ಪೋರ್ಟಬಲ್ ನೋಟ ಬೇಕಾದರೆ, ದ್ವಿಭಾಷಾ VTT ಶೈಲಿಯನ್ನು ಎಕ್ಸ್‌ಪೋರ್ಟ್ ಮಾಡಿ.",
