   "h1": "ಮೊಜಿಬಾಕೆ ಉಪಶೀರ್ಷಿಕೆಗಳನ್ನು ಸರಿಪಡಿಸುವುದು ಹೇಗೆ",
   "intro": "ಕಸದ ಅಕ್ಷರಗಳಿಂದ ತುಂಬಿದ ಉಪಶೀರ್ಷಿಕೆ ಕಡತವು ವಿರಳವಾಗಿ ಹಾಳಾಗಿರುತ್ತದೆ — ಅದನ್ನು ತಪ್ಪಾದ ಎನ್ಕೋಡಿಂಗ್‌ನೊಂದಿಗೆ ಓದಲಾಗಿರುತ್ತದೆ. ದುರಸ್ತಿ ಉಪಕರಣವು ಮೂಲ ಎನ್ಕೋಡಿಂಗ್ ಅನ್ನು ಪತ್ತೆ ಮಾಡುತ್ತದೆ ಮತ್ತು ಸರಿಯಾದ ಅಕ್ಷರಗಳನ್ನು ಮರಳಿ ಇರಿಸುತ್ತದೆ, ಸೂಚ್ಯಂಕ ಸಂಖ್ಯೆಗಳು ಮತ್ತು ಸಮಯಗಳನ್ನು ಹಾಗೆಯೇ ಬಿಡುತ್ತದೆ.",
   "ctaText": "ಮೊಜಿಬಾಕೆ ದುರಸ್ತಿ ಉಪಕರಣವನ್ನು ತೆರೆಯಿರಿ"
