     "ಬದಲಿ ಅಕ್ಷರವು ವಿಭಜಿಸುವ ರೇಖೆಯಾಗಿದೆ. `�` ಎಂದರೆ ಬೈಟ್‌ಗಳನ್ನು ಈಗಾಗಲೇ **ಹಿಂದಿನ ಹಂತದಲ್ಲಿ** (ಸಾಧರಣವಾಗಿ ಫೈಲ್ ಅನ್ನು ಓದುವ ಮತ್ತು ಅದನ್ನು ಮತ್ತೆ ಉಳಿಸುವ ಕೆಲವು ಪ್ರೋಗ್ರಾಂ) தூக்கி ಎಸೆಯಲಾಗಿದೆ, ಮತ್ತು ಏನು ಕೈಬಿಡಲಾಗಿದೆ ಎಂಬುದರ ಬಗ್ಗೆ ಯಾವುದೇ ದಾಖಲೆಯಿಲ್ಲ. ಆ ಹಂತದಲ್ಲಿ ಹಿಂದಕ್ಕೆ ತಾರ್ಕಿಸಲು ಏನೂ ಇಲ್ಲ — ಯಾರೂ ಅದನ್ನು ಸರಿಪಡಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.",
     "ಆದ್ದರಿಂದ ದುರಸ್ತಿ ಪುಟವು ಎರಡು ಪ್ರಕರಣಗಳನ್ನು ವಿಭಿನ್ನವಾಗಿ ನಿರ್ವಹಿಸುತ್ತದೆ. ಫೈಲ್ ಅನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ ಮತ್ತು ಮೂಲ ಬೈಟ್‌ಗಳು ಹಾಗೇ ಇರುತ್ತವೆ, ಇದು ಪ್ರತಿ ಎನ್ಕೋಡಿಂಗ್ ಅನ್ನು ಪ್ರಯತ್ನಿಸಲು ಅನುವು ಮಾಡಿಕೊಡುತ್ತದೆ; ಅಂಟಿಸಿದ ಪಠ್ಯವು ಈಗಾಗಲೇ ಬದಲಿ ಅಕ್ಷರವನ್ನು ಹೊಂದಿದ್ದರೆ, ಅದು ಸ್ಪಷ್ಟವಾಗಿ ಹೇಳುತ್ತದೆ: \"ಸರಿಪಡಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ, ದಯವಿಟ್ಟು ಮೂಲ ಫೈಲ್ ಅನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ\".",
