     "**ಪದ ಕೋಷ್ಟಕವನ್ನು ಉಳಿಸಲಾಗಿಲ್ಲ.** ನೀವು ಪುಟವನ್ನು ತೆರೆದ ಪ್ರತಿ ಬಾರಿಯೂ ಇದು ಖಾಲಿಯಾಗಿರುತ್ತದೆ, ಆದ್ದರಿಂದ ನಿಮ್ಮ ಸ್ವಂತ ಪಠ್ಯ ಫೈಲ್ ಅನ್ನು ಇರಿಸಿ ಮತ್ತು ಅದನ್ನು ರವಾನಿಸಿ."
