   "desc": "ಓದಲು ತುಂಬಾ ವೇಗವಾದ ಉಪಶೀರ್ಷಿಕೆಗಳು — ಕಡಿಮೆ ಅವಧಿ ಅಥವಾ ದೀರ್ಘ ಪಠ್ಯವೇ? QC ಯು ಪ್ರತಿ ಸೆಕೆಂಡಿಗೆ 20 ಅಕ್ಷರಗಳಿಗಿಂತ ಹೆಚ್ಚಿನ ನಮೂದುಗಳನ್ನು ಫ್ಲ್ಯಾಗ್ ಮಾಡುತ್ತದೆ (CJK ಗಾಗಿ 9 ಹಾಂಜಿ); ಅವಧಿಗಳು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಸರಿಪಡಿಸುತ್ತವೆ, ಪಠ್ಯವನ್ನು ಸಂಪಾದಿಸಬೇಕಾಗುತ್ತದೆ.",
